blocks=['<section id="effects"><div class="eyebrow">NEW FIRSTMATE BRAINSTORM · CAPTAIN: “ACTUALLY THEY’RE ALL PRETTY COOL”</div><h2>Make the séance behave like a living thing.</h2><p>All candidates remain on the board. Positive reaction is not a selection to build all of them. The strongest proposed combination is <b>human-gated baquet + recorded glass tone + hand knocks + slate fallback</b>; spirit hands already fit the touch puzzle. These replace existing cues and preserve the 28-minute draft.</p><div class="grid2">']
for title,scope,where,value,cost,reset in effects:
 blocks.append(f'<div class="panel"><span class="badge badge-outline">{scope}</span><h3>{title}</h3><div class="eyebrow">{where} · FIRSTMATE CANDIDATE</div><p>{value}</p><p class="caption">{cost}</p><p class="caption"><b>Reset estimate:</b> {reset}.</p></div>')
blocks.append('''</div><form class="panel" data-lavish-question="effects" data-title="Séance effect selection" style="margin-top:24px"><h3>Which effects belong in this show?</h3><p>Nothing is preselected. Unchecked effects remain candidates; this does not silently reject them.</p>''')
for title,*_ in effects:blocks.append(f'<label><input type="checkbox" class="checkbox checkbox-sm" name="effect" value="{html.escape(title)}"> {title}</label>')
blocks.append('''<label for="effects-notes">Notes / variant / priority</label><textarea class="textarea textarea-bordered" id="effects-notes" name="notes" rows="3" placeholder="For example: manual baquet + recorded glass tone now; keep table tilt optional."></textarea><button class="btn btn-primary" type="submit">Queue effect selection</button><p class="caption feedback" aria-live="polite">Nothing queued.</p></form></section>''')
